import { Component } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";

export interface AgeIconProps {
	class: string;
	ageId: string;
	apexTooltip?: boolean;
	framedIcons?: boolean;
}

export const AgeIcon: Component<AgeIconProps> = (props) => {
	// TODO: This is a stub - actual age icons should be set in the xml
	const ageIcons: Record<string, string> = {
		AGE_ANTIQUITY: "url('blp:city_antiquity')",
		AGE_EXPLORATION: "url('city_exploration')",
		AGE_MODERN: "url('city_modern')",
	};

	const framedAgeIcon: Record<string, string> = {
		AGE_ANTIQUITY: "url('blp:city_antiguity_128x128')",
		AGE_EXPLORATION: "url('city_exploration_128x128')",
		AGE_MODERN: "url('city_modern_128x128')",
	};

	const ageText: Record<string, string> = {
		AGE_ANTIQUITY: "LOC_UI_CREATE_GAME_ANTIQUITY",
		AGE_EXPLORATION: "LOC_UI_CREATE_GAME_EXPLORATION",
		AGE_MODERN: "LOC_UI_CREATE_GAME_MODERN",
	};

	const ageApexText: Record<string, string> = {
		AGE_ANTIQUITY: "LOC_UI_CREATE_GAME_ANTIQUITY_APEX",
		AGE_EXPLORATION: "LOC_UI_CREATE_GAME_EXPLORATION_APEX",
		AGE_MODERN: "LOC_UI_CREATE_GAME_MODERN_APEX",
	};

	return (
		<Tooltip.Text
			bodyClass="flex flex-row justify-center"
			text={props.apexTooltip ? ageApexText[props.ageId] : ageText[props.ageId]}
		>
			<Icon
				class={props.class}
				name={props.framedIcons ? framedAgeIcon[props.ageId] : ageIcons[props.ageId]}
			/>
		</Tooltip.Text>
	);
};
